import{_ as o,a0 as p,w as d,s as r,ao as l,I as i,x as a,a1 as e,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"使用 mDNS 在局域網中輕鬆發現系統 | LCTT x X-CMD","titleTemplate":false,"description":"使用 mDNS 在局域網中輕鬆發現系統 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 mDNS 在局域網中輕鬆發現系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 mDNS 在局域網中輕鬆發現系統 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180905 Find your systems easily on a LAN with mDNS","title":"使用 mDNS 在局域網中輕鬆發現系統","tag":"201809","desc":""},"relativePath":"201809/20180905 Find your systems easily on a LAN with mDNS.md","filePath":"[post].md"}'),h={name:"201809/20180905 Find your systems easily on a LAN with mDNS.md"};function g(m,s,u,k,b,f){const t=p("Link");return d(),r("div",null,[s[20]||(s[20]=l(`<h1 id="使用-mdns-在局域網中輕鬆發現系統" tabindex="-1">使用 mDNS 在局域網中輕鬆發現系統 <a class="header-anchor" href="#使用-mdns-在局域網中輕鬆發現系統" aria-label="Permalink to “使用 mDNS 在局域網中輕鬆發現系統”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/09/mDNS-816x345.jpg" alt=""></p><p>mDNS（<ruby>多播 DNS<rt>Multicast DNS</rt></ruby>）允許系統在局域網中廣播查詢其他資源的名稱。Fedora 用户經常在沒有複雜名稱服務的路由器上接有多個 Linux 系統。在這種情況下，mDNS 允許你按名稱與多個系統通信 —— 多數情況下不用路由器。你也不必在所有本地系統上同步類似 <code>/etc/hosts</code> 之類的文件。本文介紹如何設置它。</p><p>mDNS 是一個零配置網絡服務，它已經誕生了很長一段時間。Fedora Workstation 帶有零配置系統 Avahi（它包含 mDNS）。 （mDNS 也是 Bonjour 的一部分，可在 Mac OS 上找到。）</p><p>本文假設你有兩個系統運行受支持的 Fedora 版本（27 或 28）。它們的主機名是 castor 和 pollux。</p><h3 id="安裝包" tabindex="-1">安裝包 <a class="header-anchor" href="#安裝包" aria-label="Permalink to “安裝包”">​</a></h3><p>確保系統上安裝了 nss-mdns 和 avahi 軟件包。你可能是不同的版本，這也沒問題：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rpm -q nss-mdns avahi</span></span>
<span class="line"><span>nss-mdns-0.14.1-1.fc28.x86_64</span></span>
<span class="line"><span>avahi-0.7-13.fc28.x86_64</span></span></code></pre></div><p>Fedora Workstation 默認提供這兩個包。如果不存在，請安裝它們：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install nss-mdns avahi</span></span></code></pre></div><p>確保 <code>avahi-daemon.service</code> 單元已啓用並正在運行。同樣，這是 Fedora Workstation 的默認設置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable --now avahi-daemon.service</span></span></code></pre></div><p>雖然是可選的，但你可能還需要安裝 avahi-tools 軟件包。該軟件包包括許多方便的程序，用於檢查系統上的零配置服務的工作情況。使用這個 <code>sudo</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install avahi-tools</span></span></code></pre></div><p><code>/etc/nsswitch.conf</code> 控制系統使用哪個服務用於解析，以及它們的順序。你應該在那個文件中看到這樣的一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>hosts: files mdns4_minimal [NOTFOUND=return] dns myhostname</span></span></code></pre></div><p>注意命令 <code>mdns4_minimal [NOTFOUND=return]</code>。它們告訴你的系統使用多播 DNS 解析程序將主機名解析為 IP 地址。即使該服務有效，如果名稱無法解析，也會嘗試其餘服務。</p><p>如果你沒有看到與此類似的配置，則可以（以 root 用户身份）對其進行編輯。但是，nss-mdns 包會為你處理此問題。如果你對自己編輯它感到不舒服，請刪除並重新安裝該軟件包以修復該文件。</p><p>在<strong>兩個系統</strong>中執行同樣的步驟 。</p><h3 id="設置主機名並測試" tabindex="-1">設置主機名並測試 <a class="header-anchor" href="#設置主機名並測試" aria-label="Permalink to “設置主機名並測試”">​</a></h3><p>現在你已完成常見的配置工作，請使用以下方法之一設置每個主機的名稱：</p>`,21)),i("ol",null,[i("li",null,[s[1]||(s[1]=a("如果你正在使用 Fedora Workstation，",-1)),e(t,{href:"https://fedoramagazine.org/set-hostname-fedora/"},{default:n(()=>[...s[0]||(s[0]=[a("你可以使用這個步驟",-1)])]),_:1}),s[2]||(s[2]=a("。",-1))]),s[3]||(s[3]=i("li",null,[a("如果沒有，請使用 "),i("code",null,"hostnamectl"),a(" 來做。在第一台機器上這麼做："),i("code",null,"$ hostnamectl set-hostname castor"),a("。")],-1)),s[4]||(s[4]=i("li",null,[a("你還可以編輯 "),i("code",null,"/etc/avahi/avahi-daemon.conf"),a("，刪除主機名設置行上的註釋，並在那裏設置名稱。但是，默認情況下，Avahi 使用系統提供的主機名，因此你"),i("strong",null,"不應該"),a("需要此方法。")],-1))]),s[21]||(s[21]=l(`<p>接下來，重啓 Avahi 守護進程，以便它接收更改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl restart avahi-daemon.service</span></span></code></pre></div><p>然後正確設置另一台機器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hostnamectl set-hostname pollux</span></span>
<span class="line"><span>$ sudo systemctl restart avahi-daemon.service</span></span></code></pre></div><p>只要你的路由器沒有禁止 mDNS 流量，你現在應該能夠登錄到 castor 並 ping 通另一台機器。你應該使用默認的 .local 域名，以便解析正常工作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping pollux.local</span></span>
<span class="line"><span>PING pollux.local (192.168.0.1) 56(84) bytes of data.</span></span>
<span class="line"><span>64 bytes from 192.168.0.1 (192.168.0.1): icmp_seq=1 ttl=64 time=3.17 ms</span></span>
<span class="line"><span>64 bytes from 192.168.0.1 (192.168.0.1): icmp_seq=2 ttl=64 time=1.24 ms</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>如果你在 pollux <code>ping castor.local</code>，同樣的技巧也適用。現在在網絡中訪問你的系統更方便了！</p><p>此外，如果你的路由器也支持這個服務，請不要感到驚訝。現代 WiFi 和有線路由器通常提供這些服務，以使消費者的生活更輕鬆。</p><p>此過程適用於大多數系統。但是，如果遇到麻煩，請使用 avahi-browse 和 avahi-tools 軟件包中的其他工具來查看可用的服務。</p><hr>`,10)),i("p",null,[s[6]||(s[6]=a("via: ",-1)),e(t,{href:"https://fedoramagazine.org/find-systems-easily-lan-mdns/"},{default:n(()=>[...s[5]||(s[5]=[a("https://fedoramagazine.org/find-systems-easily-lan-mdns/",-1)])]),_:1})]),i("p",null,[s[11]||(s[11]=a("作者：",-1)),e(t,{href:"https://fedoramagazine.org/author/pfrields/"},{default:n(()=>[...s[7]||(s[7]=[a("Paul W. Frields",-1)])]),_:1}),s[12]||(s[12]=a(" \u2028選題：",-1)),e(t,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[8]||(s[8]=[a("lujun9972",-1)])]),_:1}),s[13]||(s[13]=a(" \u2028譯者：",-1)),e(t,{href:"https://github.com/geekpi"},{default:n(()=>[...s[9]||(s[9]=[a("geekpi",-1)])]),_:1}),s[14]||(s[14]=a(" \u2028校對：",-1)),e(t,{href:"https://github.com/wxy"},{default:n(()=>[...s[10]||(s[10]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[17]||(s[17]=a("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[15]||(s[15]=[a("LCTT",-1)])]),_:1}),s[18]||(s[18]=a(" 原創編譯，",-1)),e(t,{href:"https://linux.cn/"},{default:n(()=>[...s[16]||(s[16]=[a("Linux中國",-1)])]),_:1}),s[19]||(s[19]=a(" 榮譽推出",-1))])])}const N=o(h,[["render",g]]);export{v as __pageData,N as default};
